317	  public void replayKnownUses(UUID execution, UUID attempt, Map<String, String> usage) {
318	    if (usage.isEmpty()) {
319	      return;
320	    }
321	    if (usage.values().stream().anyMatch(value -> !"USED".equals(value))) {
322	      throw new IllegalArgumentException("Invalid positive secret usage report");
323	    }
324	    var releases =
325	        jdbc.queryForList(
326	            ("SELECT * FROM studio_secret_use_audit WHERE execution_id=? AND attempt_id=? AND decis"
327	                + "ion_stage='DISPATCH' AND outcome='RESOLVED'"),
328	            execution,
329	            attempt.toString());
330	    var available = new java.util.HashSet<String>();
331	    releases.forEach(row -> available.add((String) row.get("secret_id")));
332	    if (!available.containsAll(usage.keySet())) {
333	      throw new IllegalArgumentException("Missing scoped resolved secret release");
334	    }
335	    for (var row : releases) {
336	      if (usage.containsKey((String) row.get("secret_id"))) {
337	        audit.recordUsage(release(row), SecretUseAuditRecorder.UsageOutcome.USED);
338	      }
339	    }
340	  }
