346	                + "ion_stage='DISPATCH'"),
347	            execution,
348	            attempt.toString());
349	    var declared = new java.util.HashSet<String>();
350	    rows.forEach(row -> declared.add((String) row.get("secret_id")));
351	    if (!declared.containsAll(usage.keySet())) {
352	      throw new IllegalArgumentException("Invalid secret usage report");
353	    }
