 15	public class PartitionManager {
 16	
 17	  private static final Logger LOG = LoggerFactory.getLogger(PartitionManager.class);
 18	  private static final DateTimeFormatter PARTITION_FMT = DateTimeFormatter.ofPattern("yyyy_MM");
 19	  private static final DateTimeFormatter SQL_DATE_FMT = DateTimeFormatter.ofPattern("yyyy-MM-dd");
 20	
