 31	  /** The range-partition key of each managed table (V1, V7). */
 32	  private static final Map<String, String> PARTITION_KEYS =
 33	      Map.of(
 34	          "execution_results", "started_at",
 35	          "ui_test_executions", "started_at",
 36	          "report_executions", "executed_at",
 37	          "studio_secret_use_audit", "release_occurred_at",
 38	          "studio_observed_secret_read_entries", "occurred_at",
 39	          "studio_observed_no_send_decisions", "occurred_at",
