 47	  private final JdbcTemplate jdbc;
 48	  private final String parentTable;
 49	
 50	  public PartitionManager(JdbcTemplate jdbc, String parentTable) {
 51	    if (!ALLOWED_TABLES.contains(parentTable)) {
 52	      throw new IllegalArgumentException("Unknown partitioned table: " + parentTable);
 53	    }
 54	    this.jdbc = jdbc;
 55	    this.parentTable = parentTable;
 56	  }
 57	
 58	  public boolean isPartitionedTable() {
 59	    try {
 60	      Integer count =
 61	          jdbc.queryForObject(
 62	              """
 63	              SELECT COUNT(*) FROM pg_partitioned_table pt
 64	              JOIN pg_class c ON c.oid = pt.partrelid
 65	              WHERE c.relname = ?
 66	              """,
 67	              Integer.class,
 68	              parentTable);
 69	      return count != null && count > 0;
 70	    } catch (Exception e) {
 71	      LOG.debug("Table {} does not exist or is not partitioned: {}", parentTable, e.getMessage());
 72	      return false;
 73	    }
 74	  }
 75	
 76	  /**
 77	   * Ensures the monthly partitions for the current UTC month and the next {@code lookaheadMonths}.
 78	   *
 79	   * <p>Returns the names of every partition that exists for that window once the call is done,
 80	   * whether it created them or found them.
 81	   */
 82	  public List<String> ensurePartitions(int lookaheadMonths) {
 83	    if (!isPartitionedTable()) {
 84	      LOG.debug(
 85	          "Skipping partition creation for {} — table not partitioned or missing", parentTable);
 86	      return List.of();
 87	    }
 88	
 89	    YearMonth current = YearMonth.now(ZoneOffset.UTC);
 90	    List<String> ensured = new ArrayList<>();
 91	
 92	    for (int i = 0; i <= lookaheadMonths; i++) {
 93	      YearMonth month = current.plusMonths(i);
 94	      String partitionName = partitionName(month);
 95	      try {
 96	        ensurePartition(month);
 97	        ensured.add(partitionName);
 98	      } catch (Exception e) {
 99	        LOG.error("Failed to create partition {}: {}", partitionName, e.getMessage());
100	      }
101	    }
102	
103	    return ensured;
104	  }
105	
106	  /**
107	   * Creates the partition for {@code month} unless it already exists, moving any rows for that
108	   * month out of the DEFAULT partition into it.
109	   *
110	   * <p><b>Why the move.</b> A bare {@code CREATE TABLE … PARTITION OF … FOR VALUES …} fails while
111	   * the DEFAULT partition holds a row inside the new range ("updated partition constraint for
112	   * default partition would be violated"). Any insert that lands before the month's partition
113	   * exists — the dev seed (Flyway runs before any bootstrap), an API pod accepting a run before a
114	   * worker has bootstrapped, a missed monthly run — therefore used to make the month permanently
115	   * uncreatable, and the partition health indicator DOWN for good.
116	   *
117	   * <p>One {@code DO} block is one statement and so one transaction: the rows are moved aside out
118	   * of DEFAULT (a single {@code DELETE … RETURNING}), the partition is created and the rows are
119	   * re-inserted through the parent, and all applicable evidence guards installed, or none of it
120	   * happens. Existing leaves are repaired under the same creation lock. {@code CREATE … PARTITION
121	   * OF} locks and rescans DEFAULT, so a row for the month committed in between fails the block
122	   * rather than being stranded. A transaction-scoped advisory lock per parent table serialises
123	   * concurrent callers (every pod bootstraps), and the existence check is repeated under it.
124	   *
125	   * @return {@code true} when the partition was absent before the call and exists after it
126	   */
127	  boolean ensurePartition(YearMonth month) {
128	    String partitionName = partitionName(month);
129	    boolean existed = listPartitions().contains(partitionName);
130	    String guardInstallation =
131	        SECRET_EVIDENCE_TABLES.contains(parentTable)
132	            ? "PERFORM studio_secret_install_partition_guards('"
133	                + parentTable
134	                + "','"
135	                + partitionName
136	                + "');"
137	            : "";
138	    String rangeStart = month.atDay(1).format(SQL_DATE_FMT);
139	    String rangeEnd = month.plusMonths(1).atDay(1).format(SQL_DATE_FMT);
140	    String defaultPartition = parentTable + "_default";
141	    String partitionKey = PARTITION_KEYS.get(parentTable);
142	    String staging = "partition_move_" + partitionName;
143	
144	    // Every interpolated value is a whitelisted table name, a name derived from it, or a date this
145	    // class formatted; inside the block they are quoted again with %I / %L.
146	    String block =
147	        """
148	DO $partition$
149	DECLARE
150	  cols  text;
151	  moved bigint := 0;
152	BEGIN
153	  PERFORM pg_advisory_xact_lock(hashtext('checks-partition:' || '%1$s'));
154	  IF to_regclass('%2$s') IS NOT NULL THEN
155	    EXECUTE format('LOCK TABLE %%I IN ACCESS EXCLUSIVE MODE', '%2$s');
156	    %8$s
157	    RETURN;
158	  END IF;
159	  IF to_regclass('%3$s') IS NOT NULL THEN
160	    SELECT string_agg(quote_ident(attname), ', ' ORDER BY attnum) INTO cols
161	      FROM pg_attribute
162	     WHERE attrelid = '%1$s'::regclass AND attnum > 0 AND NOT attisdropped;
163	    EXECUTE format('CREATE TEMP TABLE %%I ON COMMIT DROP AS SELECT %%s FROM %%I WHERE false',
164	                   '%6$s', cols, '%3$s');
165	    -- One statement, so a row committed to DEFAULT between a copy and a delete cannot be
166	    -- deleted without having been copied.
167	    EXECUTE format('WITH moved AS (DELETE FROM %%I WHERE %%I >= %%L AND %%I < %%L'
168	                   || ' RETURNING %%s) INSERT INTO %%I SELECT * FROM moved',
169	                   '%3$s', '%7$s', '%4$s', '%7$s', '%5$s', cols, '%6$s');
170	    GET DIAGNOSTICS moved = ROW_COUNT;
171	  END IF;
172	  EXECUTE format('CREATE TABLE %%I PARTITION OF %%I FOR VALUES FROM (%%L) TO (%%L)',
173	                 '%2$s', '%1$s', '%4$s', '%5$s');
174	  %8$s
175	  IF moved > 0 THEN
176	    EXECUTE format('INSERT INTO %%I (%%s) SELECT %%s FROM %%I', '%1$s', cols, cols, '%6$s');
177	    RAISE NOTICE 'partition %% created with %% row(s) moved from %%', '%2$s', moved, '%3$s';
178	  END IF;
179	END
180	$partition$
181	"""
182	            .formatted(
183	                parentTable,
184	                partitionName,
185	                defaultPartition,
186	                rangeStart,
187	                rangeEnd,
188	                staging,
189	                partitionKey,
190	                guardInstallation);
191	
192	    jdbc.execute(block);
193	    boolean created = listPartitions().contains(partitionName);
194	    LOG.info(
195	        "partition_created table={} range=[{}, {}) present={}",
196	        partitionName,
197	        rangeStart,
198	        rangeEnd,
199	        created);
200	    return !existed && created;
201	  }
202	
203	  private String partitionName(YearMonth month) {
204	    return parentTable + "_" + month.format(PARTITION_FMT);
205	  }
