207	  public PartitionHealthStatus checkHealth(int lookaheadDays) {
208	    if (!isPartitionedTable()) {
209	      return new PartitionHealthStatus(
210	          !SECRET_EVIDENCE_TABLES.contains(parentTable),
211	          SECRET_EVIDENCE_TABLES.contains(parentTable) ? parentTable : null);
212	    }
213	
214	    YearMonth targetMonth =
215	        YearMonth.from(java.time.LocalDate.now(ZoneOffset.UTC).plusDays(lookaheadDays));
216	    String expectedPartition = parentTable + "_" + targetMonth.format(PARTITION_FMT);
217	
218	    Set<String> existingPartitions = listPartitions();
219	
220	    if (SECRET_EVIDENCE_TABLES.contains(parentTable)) {
221	      for (String leaf : existingPartitions) {
222	        if (!hasApplicableSecretGuards(leaf)) {
223	          return new PartitionHealthStatus(false, leaf);
224	        }
225	      }
226	    }
227	    if (existingPartitions.contains(expectedPartition)) {
228	      return new PartitionHealthStatus(true, null);
229	    }
230	    return new PartitionHealthStatus(false, expectedPartition);
231	  }
232	
233	  private boolean hasApplicableSecretGuards(String leaf) {
234	    String commitFunction =
235	        switch (parentTable) {
236	          case "studio_observed_no_send_decisions" -> "studio_observed_no_send_commit_guard()";
237	          case "studio_observed_terminal_secret_settlements" ->
238	              "studio_observed_terminal_commit_guard()";
239	          default -> null;
240	        };
241	    Boolean immutable =
242	        jdbc.queryForObject(
243	            ("SELECT EXISTS(SELECT 1 FROM pg_trigger t WHERE t.tgrelid=to_regclass(?) "
244	                + "AND t.tgname='tr_secret_evidence_leaf_truncate' AND "
245	                + "t.tgfoid=to_regprocedure('studio_secret_audit_immutable()') AND "
246	                + "t.tgtype=34 AND t.tgenabled IN ('O','A')) AND EXISTS(SELECT 1 FROM "
247	                + "pg_trigger t WHERE t.tgrelid=to_regclass(?) AND "
248	                + "t.tgfoid=to_regprocedure('studio_secret_audit_immutable()') AND "
249	                + "(t.tgtype & 27)=27 AND t.tgenabled IN ('O','A')) AND (SELECT "
250	                + "pg_get_expr(relpartbound,oid)<>'DEFAULT' FROM pg_class WHERE "
251	                + "oid=to_regclass(?))"),
252	            Boolean.class,
253	            leaf,
254	            leaf,
255	            leaf);
256	    if (!Boolean.TRUE.equals(immutable)) {
257	      return false;
258	    }
259	    if (commitFunction == null) {
260	      return true;
261	    }
262	    return Boolean.TRUE.equals(
263	        jdbc.queryForObject(
264	            ("SELECT EXISTS(SELECT 1 FROM pg_trigger t WHERE t.tgrelid=to_regclass(?) "
265	                + "AND t.tgfoid=to_regprocedure(?) AND t.tgtype=5 AND t.tgconstraint<>0 AND "
266	                + "t.tgdeferrable AND t.tginitdeferred AND t.tgenabled IN ('O','A'))"),
267	            Boolean.class,
268	            leaf,
269	            commitFunction));
270	  }
271	
272	  public int countFuturePartitions() {
273	    if (!isPartitionedTable()) {
274	      return 0;
275	    }
276	
277	    YearMonth current = YearMonth.now(ZoneOffset.UTC);
278	    String currentPartition = parentTable + "_" + current.format(PARTITION_FMT);
279	
280	    Set<String> partitions = listPartitions();
281	    return (int) partitions.stream().filter(p -> p.compareTo(currentPartition) > 0).count();
282	  }
283	
284	  public int pruneExpired(int retentionMonths) {
285	    if (!isPartitionedTable()) {
286	      LOG.debug(
287	          "Skipping partition pruning for {} — table not partitioned or missing", parentTable);
288	      return 0;
289	    }
290	
291	    YearMonth cutoff = YearMonth.now(ZoneOffset.UTC).minusMonths(retentionMonths);
292	    String cutoffPartition = parentTable + "_" + cutoff.format(PARTITION_FMT);
293	    Set<String> partitions = listPartitions();
294	    int pruned = 0;
295	
296	    for (String partition : partitions) {
297	      if (partition.compareTo(cutoffPartition) >= 0) {
298	        continue;
299	      }
300	
301	      try {
302	        try {
303	          jdbc.execute(
304	              "ALTER TABLE " + parentTable + " DETACH PARTITION " + partition + " CONCURRENTLY");
305	        } catch (Exception concurrentEx) {
306	          LOG.debug(
307	              "DETACH CONCURRENTLY failed for {}, falling back to blocking DETACH", partition);
308	          jdbc.execute("ALTER TABLE " + parentTable + " DETACH PARTITION " + partition);
309	        }
310	        jdbc.execute("DROP TABLE " + partition);
311	        LOG.info("partition_pruned table={} action=detach_drop", partition);
312	        pruned++;
313	      } catch (Exception e) {
314	        LOG.warn("partition_prune_skipped table={} reason={}", partition, e.getMessage());
315	      }
316	    }
317	
318	    return pruned;
319	  }
320	
321	  private Set<String> listPartitions() {
322	    return jdbc
323	        .queryForList(
324	            """
325	            SELECT c.relname FROM pg_class c
326	            JOIN pg_inherits i ON c.oid = i.inhrelid
327	            WHERE i.inhparent = ?::regclass
328	            """,
329	            parentTable)
330	        .stream()
331	        .map(row -> (String) row.get("relname"))
332	        .collect(Collectors.toSet());
333	  }
334	
335	  public record PartitionHealthStatus(boolean up, String missingPartition) {}
336	}

