733	CREATE FUNCTION studio_secret_install_partition_guards(parent_key text,leaf_key text) RETURNS void LANGUAGE plpgsql AS $$
734	DECLARE parent_oid regclass; leaf_oid regclass;
735	BEGIN
736	 IF parent_key NOT IN ('studio_secret_use_audit','studio_observed_secret_read_entries','studio_observed_no_send_decisions','studio_observed_terminal_secret_settlements')
