743	  EXECUTE format('CREATE TRIGGER tr_secret_evidence_leaf_truncate BEFORE TRUNCATE ON %s FOR EACH STATEMENT EXECUTE FUNCTION studio_secret_audit_immutable()',leaf_oid);
