746	  SELECT 1 FROM pg_trigger WHERE tgrelid=leaf_oid AND tgname='tr_observed_no_send_commit') THEN
747	  EXECUTE format('CREATE CONSTRAINT TRIGGER tr_observed_no_send_commit AFTER INSERT ON %s DEFERRABLE INITIALLY DEFERRED FOR EACH ROW EXECUTE FUNCTION studio_observed_no_send_commit_guard()',leaf_oid);
