756	-- Backend bootstrap extends this family before traffic, with the existing retention window.
757	DO $$ DECLARE month_start date; i integer; family text; leaf text; BEGIN
758	 month_start:=date_trunc('month',clock_timestamp() AT TIME ZONE 'UTC')::date;
759	 FOREACH family IN ARRAY ARRAY['studio_secret_use_audit','studio_observed_secret_read_entries','studio_observed_no_send_decisions','studio_observed_terminal_secret_settlements'] LOOP
760	  FOR i IN 0..2 LOOP
761	   leaf:=family||'_'||to_char(month_start+(i||' months')::interval,'YYYY_MM');
762	   EXECUTE format('CREATE TABLE %I PARTITION OF %I FOR VALUES FROM (%L) TO (%L)',leaf,family,
763	    (month_start+(i||' months')::interval)::date,(month_start+((i+1)||' months')::interval)::date);
764	   PERFORM studio_secret_install_partition_guards(family,leaf);
765	  END LOOP;
766	 END LOOP;
767	END $$;
