   455	CREATE FUNCTION studio_secret_guided_exact_reference(session_key text,scope_key text,step_key text,secret_key text,reference_key text)
   456	 RETURNS boolean LANGUAGE sql STABLE AS $$
   457	 SELECT count(*)=1 FROM studio_guided_source_manifests m,
