   459	  WHERE m.session_id=session_key AND m.scope_hash=scope_key
   460	   AND m.manifest_hash=studio_publication_hash(m.manifest)
   461	   AND reference->>'referenceId'=reference_key AND length(reference_key) BETWEEN 1 AND 256
   462	   AND reference->>'kind'='secretRef' AND reference->>'referenceName'=secret_key
   463	   AND reference->>'stepId'=step_key AND reference->>'intendedSlot'='fill.value'
