   465	$$;
   466	CREATE FUNCTION studio_secret_guided_input_reference(session_key text,scope_key text,admission_key text)
   467	 RETURNS text LANGUAGE sql STABLE AS $$
   468	 SELECT CASE WHEN count(*)=1 THEN min(input->'provenance'->>'referenceId') ELSE NULL END
   469	 FROM studio_guided_actions a JOIN studio_guided_materializations material ON material.session_id=a.session_id
   470	 JOIN studio_guided_source_manifests source ON source.session_id=a.session_id,
   471	 LATERAL jsonb_array_elements(material.authored_inputs->'inputs') input
   472	 WHERE a.session_id=session_key AND a.admission_id=admission_key AND material.scope_hash=scope_key
   473	  AND source.scope_hash=scope_key AND source.manifest_hash=studio_publication_hash(source.manifest)
   474	  AND material.owner_fence=(a.document->>'ownerFence')::integer
   475	  AND a.proposal->'operation'->>'kind'='fill' AND a.proposal->'operation'->'value'->>'kind'='secretRef'
   476	  AND input->>'inputId'=a.proposal->'operation'->'value'->>'sourceInputId'
   477	  AND input->>'kind'='secretRef' AND input->>'sourceStepId'=a.step_id
   478	  AND input->>'intendedSlot'='fill.value' AND NOT(input ? 'value')
   479	  AND input->'provenance'->>'referenceKind'='configuration'
   480	  AND input->'provenance'->>'kind'='secretRef' AND input->'provenance'->>'intendedSlot'='fill.value'
   481	  AND input->'provenance'->>'stepId'=a.step_id
   482	  AND input->'provenance'->>'referenceName'=input->>'secretId'
   483	  AND input->'provenance'->>'configurationRevision'=material.configuration_revision
   484	  AND studio_secret_guided_exact_reference(session_key,scope_key,a.step_id,input->>'secretId',input->'provenance'->>'referenceId')
   485	$$;
