   487	CREATE FUNCTION studio_secret_guided_consumed(session_key text,scope_key text,admission_key text,
   488	 step_key text,ordinal_key integer,secret_key text,attempt_key text) RETURNS boolean LANGUAGE sql STABLE AS $$
   489	 SELECT EXISTS(SELECT 1 FROM studio_guided_actions a
   490	  JOIN studio_guided_materializations m ON m.session_id=a.session_id,
   491	  LATERAL jsonb_array_elements(m.authored_inputs->'inputs') input
   492	  WHERE a.session_id=session_key AND a.admission_id=admission_key
   493	   AND a.step_id=step_key AND a.ordinal=ordinal_key
   494	   AND (a.document->>'dispatchCount')::integer=1
   495	   AND a.document->>'state' IN ('DISPATCHING','UNKNOWN_OUTCOME','FAILED','SUCCEEDED','REVOKED')
   496	   AND attempt_key=session_key||':'||(a.document->>'ownerFence')
   497	   AND m.scope_hash=scope_key AND m.owner_fence=(a.document->>'ownerFence')::integer
   498	   AND a.proposal->'operation'->>'kind'='fill'
   499	   AND a.proposal->'operation'->'value'->>'kind'='secretRef'
   500	   AND input->>'inputId'=a.proposal->'operation'->'value'->>'sourceInputId'
   501	   AND input->>'kind'='secretRef' AND input->>'secretId'=secret_key AND NOT(input ? 'value')
   502	   AND input->>'sourceStepId'=step_key AND input->>'intendedSlot'='fill.value'
   503	   AND studio_secret_guided_input_reference(session_key,scope_key,admission_key) IS NOT NULL)
   504	$$;
